CREATE TABLE dispatches(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,party_id INTEGER NOT NULL,warehouse_id INTEGER NOT NULL,date TEXT NOT NULL,number TEXT NOT NULL,reference TEXT NOT NULL,snapshot TEXT NOT NULL,value INTEGER NOT NULL CHECK(value>=0),document_id INTEGER,returned_date TEXT,UNIQUE(business_id,id),UNIQUE(business_id,number),UNIQUE(business_id,reference),UNIQUE(business_id,document_id),FOREIGN KEY(business_id,party_id) REFERENCES parties(business_id,id),FOREIGN KEY(business_id,warehouse_id) REFERENCES warehouses(business_id,id),FOREIGN KEY(business_id,document_id) REFERENCES documents(business_id,id));
CREATE TRIGGER dispatch_no_delete BEFORE DELETE ON dispatches BEGIN SELECT RAISE(ABORT,'dispatches are immutable'); END;
CREATE TRIGGER dispatch_no_update BEFORE UPDATE ON dispatches WHEN NEW.business_id!=OLD.business_id OR NEW.party_id!=OLD.party_id OR NEW.warehouse_id!=OLD.warehouse_id OR NEW.date!=OLD.date OR NEW.number!=OLD.number OR NEW.reference!=OLD.reference OR NEW.snapshot!=OLD.snapshot OR NEW.value!=OLD.value OR OLD.document_id IS NOT NULL OR OLD.returned_date IS NOT NULL BEGIN SELECT RAISE(ABORT,'dispatches are immutable'); END;
INSERT OR IGNORE INTO accounts(business_id,code,name,kind) SELECT id,'1250','Goods dispatched, invoice pending','ASSET' FROM businesses;
